package com.aoo.bcg.billing;import java.time.*;import java.util.Map;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class LedgerCorrectionServiceTest{@Test void appendsIdempotentOppositeEntryInsteadOfEditingBalance(){var repo=new InMemoryLedgerRepository();var billing=new InMemoryBillingService(repo,Clock.fixed(Instant.EPOCH,ZoneOffset.UTC),Map.of(7L,100L),"ROOM_CARD");billing.debit("charge-1",7,"ROOM_CARD",30,"ROOM");var service=new LedgerCorrectionService(billing,repo);var correction=service.reverse("repair-1","charge-1","INCIDENT");assertEquals(30,correction.delta());assertEquals(100,billing.balance(7,"ROOM_CARD"));assertSame(correction,service.reverse("repair-1","charge-1","INCIDENT"));assertEquals("CORRECTION:INCIDENT:charge-1",correction.reasonCode());}}
